const EMBEDDED_CHUNKS = [{"id": null, "text": "---\nCrop Categories: Cotton, Chilli, Tomato, Brinjal, Rice, Pulses, Brassica\nPage: 1\n---\n# Chapter 1: Identification, Biology & Crop Damage\n\nAphids (Aphis gossypii Glover, Myzus persicae Sulzer) belong to the family Aphididae (Order: Hemiptera). They are tiny, soft-bodied, pear-shaped sucking insects (1.5–2.5 mm in length) ranging from yellowish-green to dark olive green or black.", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "### Mode of Damage:\n1. Direct Sucking of Plant Sap: Both nymphs and adults cluster densely in colonies on the ventral surface of young tender leaves, terminal shoots, and floral buds. 2. Distortion & Leaf Cupping: Heavy feeding causes downward curling, crinkling, chlorotic mottling, and severe stunting of vegetative growth. 3. Sooty Mold Development: Aphids excrete copius quantities of sweet, glistening honeydew. This honeydew serves as a substrate for the black sooty mold fungus (Capnodium spp.), which covers leaf laminae and drastically impairs photosynthetic efficiency. 4.", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "Viral Disease Vectoring: Aphids serve as highly efficient vectors transmitting devastating plant viruses, including Cucumber Mosaic Virus (CMV), Potato Virus Y (PVY), and Papaya Ringspot Virus.", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "---\nCrop Categories: Cotton, Chilli, Tomato, Brinjal, Rice, Pulses, Brassica\nPage: 2\n---\n# Chapter 2: Economic Threshold Levels (ETL) & Scouting Protocol\n\n### Field Scouting Procedure:\n- Inspect 20 randomly selected plants across a zigzag or 'W' transect twice weekly during morning hours.\n- Examine 3 leaves per plant (top, middle, and bottom canopy).", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "### Economic Threshold Levels (ETL):\n- Cotton: 10% affected plants or 15–20 aphids per leaf.\n- Vegetables (Tomato / Chilli / Brinjal): 5–10 aphids per leaf before flowering stage.\n- Brassica / Mustard: 20–25 aphids per 10 cm terminal central shoot or 1.5 cm aphid colony length.\n\n---\nCrop Categories: Cotton, Chilli, Tomato, Brinjal, Rice, Pulses, Brassica\nPage: 3\n---\n# Chapter 3: Integrated Pest Management (IPM) & Recommended Interventions", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "### Cultural & Mechanical Controls:\n- Install Yellow Sticky Traps @ 15–20 traps/acre at crop canopy level to monitor and mass-trap winged alates.\n- Conserve natural predators including Ladybird beetles (Coccinella septempunctata, Cheilomenes sexmaculata), Syrphid hoverfly larvae, and Chrysoperla carnea.\n- Avoid excessive nitrogen fertilization, which produces succulent lush foliage highly attractive to sucking pests.", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "### Biological Control:\n- Foliar spray of entomopathogenic fungus *Verticillium lecanii* (1x10^8 CFU/g) or *Beauveria bassiana* @ 5 g/liter of water in late afternoon under high relative humidity (>80%).", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "### Certified Chemical Control (Package of Practices):\n- **Imidacloprid 17.8% SL**: 0.3 ml per liter of water (50–60 ml/acre).\n- **Acetamiprid 20% SP**: 0.2 g per liter of water (40 g/acre).\n- **Flonicamid 50% WG**: 0.3 g per liter of water (60 g/acre) — selective against sucking pests and safe for pollinators/natural enemies.\n- **Thiamethoxam 25% WG**: 0.25 g per liter of water (40–50 g/acre).\n- Always ensure complete spray coverage directed at the undersides of the leaves.", "source": "aphid_and_sucking_pest_management.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "PAGE 1: AGRO-CLIMATIC SEASONS IN INDIAN AGRICULTURE\nIndia possesses 15 distinct agro-climatic zones classified by the Planning Commission based on soil characteristics, rainfall patterns, temperature regimes, and water resources. Agricultural production is organized around three primary cropping cycles:\n1. Kharif Season (South-West Monsoon): Sown with the onset of monsoon rains (June-July) and harvested in autumn (September-October). Major crops: Rice, Cotton, Soybean, Maize, Groundnut, Pigeonpea (Arhar/Tur), Chilli, and Brinjal.", "source": "Farming Dataset", "page": 1, "topic": "Agro-Climatic Seasons & Planning Framework", "crop": "General"}, {"id": null, "text": "Kharif crops depend heavily on monsoon distribution and require robust field drainage to mitigate waterlogging. 2. Rabi Season (Winter Season): Sown in post-monsoon/winter months (October-November) as temperatures cool, and harvested in spring (March-April). Major crops: Wheat, Mustard, Chickpea (Gram), Potato, and Winter Vegetables. Rabi crops thrive under cooler vegetative phases and warm, dry grain-filling periods. 3. Zaid Season (Summer Season): Cultivated between March and June under assured irrigation.", "source": "Farming Dataset", "page": 1, "topic": "Agro-Climatic Seasons & Planning Framework", "crop": "General"}, {"id": null, "text": "Major crops: Summer Moong, Urad, Cucumber, Watermelon, Muskmelon, and Summer Fodder crops. 4. Perennial & Long-Duration Crops: Sugarcane, Banana, Fruit Orchards, and Plantation Crops requiring year-round water allocation. Key Planning Rule: Seasonal labels indicate general climate envelopes but sowing windows must be tailored to local district rainfall arrival, residual soil moisture, and thermal stress thresholds.", "source": "Farming Dataset", "page": 1, "topic": "Agro-Climatic Seasons & Planning Framework", "crop": "General"}, {"id": null, "text": "PAGE 2: SCIENTIFIC CROP SELECTION FRAMEWORK\nOptimal crop and varietal selection is the primary determinant of yield potential and input efficiency. Farmers must evaluate four interdependent criteria:\n1. Soil Texture & Chemistry: Heavy clay loams with high water retention are ideal for paddy; medium-to-deep black soils (Vertisols) are best for cotton and soybean; light well-drained sandy loams suit groundnut, potato, and root vegetables. 2. Water Availability & Irrigation Source: High-water crops (Rice, Sugarcane) require >1000 mm water or assured canal/tube well supply.", "source": "Farming Dataset", "page": 2, "topic": "Scientific Crop Selection Framework", "crop": "General"}, {"id": null, "text": "In water-scarce semi-arid zones, prioritize pulses (Chickpea, Pigeonpea), oilseeds (Mustard), and coarse cereals (Maize, Millets) with micro-irrigation. 3. Thermal & Photoperiodic Constraints: Terminal heat stress in Northern India during late Rabi severely restricts late-sown wheat yield; select heat-tolerant varieties (e.g., DBW-187, DBW-303). 4. Market Demand & Price Stability: Evaluate local Mandi price volatility, Minimum Support Price (MSP) coverage, proximity to cold storage, and forward contract potential.", "source": "Farming Dataset", "page": 2, "topic": "Scientific Crop Selection Framework", "crop": "General"}, {"id": null, "text": "PAGE 3: SOIL TESTING & DIAGNOSTIC INTERPRETATION\nSoil health assessment provides the foundation for site-specific nutrient management. A standard 12-parameter Soil Health Card evaluates:\n- Soil Reaction (pH):\n  * Strongly Acidic (< 5.5): Severe aluminum/manganese toxicity; phosphorus fixation. Apply Agricultural Lime (CaCO3) @ 1.5-2.5 t/ha. * Optimal Neutral (6.5 - 7.5): Maximum availability of essential macro and micronutrients. * Alkaline / Sodic (> 8.2): High sodium saturation causing soil dispersion and poor infiltration.", "source": "Farming Dataset", "page": 3, "topic": "Soil Health Card Parameters & Chemistry", "crop": "General"}, {"id": null, "text": "Apply Agricultural Gypsum (CaSO4.2H2O) @ 1-2 t/ha with green manuring (Dhaincha - Sesbania aculeata). - Electrical Conductivity (EC - Salinity in dS/m):\n  * Normal: < 1.0 dS/m; Critical (> 2.0 dS/m): Osmotic stress and root desiccation; requires flushing and leaching with quality water. - Organic Carbon (OC %):\n  * Low (< 0.50%): Depleted microbial biomass; apply 5-10 t/acre Farm Yard Manure (FYM), vermicompost, or biochar. * Medium (0.50 - 0.75%); High (> 0.75%): Optimal cation exchange capacity and biological cycling.", "source": "Farming Dataset", "page": 3, "topic": "Soil Health Card Parameters & Chemistry", "crop": "General"}, {"id": null, "text": "PAGE 4: MACRO & MICRONUTRIENT CRITICAL THRESHOLDS\nStandard soil fertility ratings (0-15 cm plow layer):\n1. Available Nitrogen (Alkaline Permanganate Method): Low (< 280 kg/ha); Medium (280-560 kg/ha); High (> 560 kg/ha). Deficiency causes uniform pale yellowing of older leaves. 2. Available Phosphorus (Olsen / Bray P2O5): Low (< 23 kg/ha); Medium (23-56 kg/ha); High (> 56 kg/ha). Deficiency produces dark purple/bronze leaf margins and stunted root proliferation. Apply Single Super Phosphate (SSP) or DAP with mycorrhiza biofertilizers. 3.", "source": "Farming Dataset", "page": 4, "topic": "Macro & Micronutrient Scientific Benchmarks", "crop": "General"}, {"id": null, "text": "Available Potassium (Ammonium Acetate K2O): Low (< 140 kg/ha); Medium (140-280 kg/ha); High (> 280 kg/ha). Key for drought resistance, stomatal regulation, and grain test weight. 4. Essential Micronutrients (DTPA Extractable):\n   - Zinc (Zn): Critical level 0.6 ppm. Deficient in 40%+ Indian soils. Apply Zinc Sulfate (21% Zn @ 10-15 kg/acre or 33% monohydrate @ 6-8 kg/acre). - Iron (Fe): Critical level 4.5 ppm. Foliar spray of 0.5% FeSO4 for interveinal chlorosis in calcareous soils. - Boron (B): Critical level 0.5 ppm.", "source": "Farming Dataset", "page": 4, "topic": "Macro & Micronutrient Scientific Benchmarks", "crop": "General"}, {"id": null, "text": "Deficiency causes hollow heart in potato, internal necrosis in mango, and flower drop in tomato. Apply Borax @ 2-3 kg/acre. - Sulfur (S): Critical level 10.0 ppm. Essential for oil synthesis in Mustard, Soybean, and Groundnut.", "source": "Farming Dataset", "page": 4, "topic": "Macro & Micronutrient Scientific Benchmarks", "crop": "General"}, {"id": null, "text": "PAGE 5: SEED QUALITY, GERMINATION & SEED TREATMENT\nCertified high-vigor seeds improve germination efficiency and stand establishment by 15-20%. Seed Classes in India: Breeder Seed (Yellow tag, 100% purity) -> Foundation Seed (White tag, 99.5% purity) -> Certified Seed (Blue tag, minimum 98% genetic purity and 85%+ germination). Integrated Seed Treatment Sequence (FIR Rule - Fungicide, Insecticide, Rhizobium/Biofertilizer):\n1.", "source": "Farming Dataset", "page": 5, "topic": "Seed Quality, Certified Classes & Treatments", "crop": "General"}, {"id": null, "text": "Fungicidal Treatment: Treat seed with Carbendazim (2g/kg), Thiram (3g/kg), or biological Trichoderma viride (5-10g/kg) to eliminate seed-borne smuts, bunts, and damping-off pathogens. 2. Insecticidal Treatment: Treat with Imidacloprid 70% WS @ 3g/kg or Thiamethoxam 30% FS @ 5ml/kg to safeguard germinating seedlings against early termites, aphids, thrips, and wireworms for 25-30 days. 3.", "source": "Farming Dataset", "page": 5, "topic": "Seed Quality, Certified Classes & Treatments", "crop": "General"}, {"id": null, "text": "Biofertilizer Inoculation: Apply Azotobacter / Azospirillum (for cereals) or Rhizobium culture (for pulses/oilseeds) + Phosphate Solubilizing Bacteria (PSB) @ 10g/kg seed with 10% jaggery solution as sticking agent. Dry in shade before sowing.", "source": "Farming Dataset", "page": 5, "topic": "Seed Quality, Certified Classes & Treatments", "crop": "General"}, {"id": null, "text": "PAGE 6: RICE (PADDY) CULTIVATION PROTOCOLS\nOptimal Soil: Heavy clay to clay loam, pH 5.5-7.0. Sowing & Transplanting: Nursery sowing mid-May to mid-June; transplant 25-30 day seedlings @ 2-3 seedlings/hill with 20x15 cm spacing. Direct Seeded Rice (DSR) using tar-watter technique saves 25% water. Water Management (Alternate Wetting and Drying - AWD):\n- Transplanting to Tillering: Maintain 2-3 cm shallow standing water for first 15 days to suppress weed emergence.", "source": "Farming Dataset", "page": 6, "topic": "Rice (Paddy) Agronomy, Water Depth & Fertilizer Splits", "crop": "Rice (Paddy)"}, {"id": null, "text": "- Active Tillering to Panicle Initiation: Allow water to subside until hairline cracks appear (3-4 days interval), then irrigate to 3 cm depth. AWD conserves 30% irrigation water. - Flowering & Anthesis: Maintain continuous submergence of 4-5 cm. Water stress during heading induces spikelet sterility. - Pre-Harvest: Drain water 10-12 days before combine harvest. Nutrient Schedule (Per Acre): Basal: 25 kg DAP + 20 kg MOP + 10 kg Zinc Sulfate (21%); 1st Top Dressing (21 DAT): 35 kg Urea; 2nd Top Dressing (42 DAT): 35 kg Urea. Avoid excessive nitrogen to prevent Bacterial Leaf Blight and BPH.", "source": "Farming Dataset", "page": 6, "topic": "Rice (Paddy) Agronomy, Water Depth & Fertilizer Splits", "crop": "Rice (Paddy)"}, {"id": null, "text": "PAGE 7: RICE PEST & PATHOGEN MANAGEMENT\n1. Rice Blast (Magnaporthe oryzae): Diamond-shaped lesions with grey center and brown margins; neck blast causes lodging. Spray Tricyclazole 75% WP @ 0.6g/L or Azoxystrobin 18.2% + Difenoconazole 11.4% SC @ 1 ml/L. 2. Sheath Blight (Rhizoctonia solani): Snake-skin like greenish-grey lesions on sheaths near water line. Apply Hexaconazole 5% SC @ 2ml/L or Validamycin 3% L @ 2.5ml/L. 3. Brown Plant Hopper (Nilaparvata lugens): Causes circular \"hopper burn\" patches.", "source": "Farming Dataset", "page": 7, "topic": "Rice Integrated Pest & Disease Management", "crop": "Rice (Paddy)"}, {"id": null, "text": "Drain field; spray Pymetrozine 50% WDG @ 0.6g/L or Triflumezopyrim 10% SC @ 0.5ml/L directed at stem bases. 4. Yellow Stem Borer (Scirpophaga incertulas): Produces dead hearts (vegetative) and white ears (reproductive). Install pheromone traps @ 8/acre; apply Chlorantraniliprole 0.4% GR @ 4 kg/acre. Disclaimer: Chemical options are illustrative; verify official state university advisory and product labels before application.", "source": "Farming Dataset", "page": 7, "topic": "Rice Integrated Pest & Disease Management", "crop": "Rice (Paddy)"}, {"id": null, "text": "PAGE 8: WHEAT (TRITICUM AESTIVUM) PRODUCTION GUIDE\nSoil Requirement: Well-drained alluvial and clay loam soils, pH 6.0-7.5. Sowing Window: Timely sown: Nov 1 to Nov 20; Late sown: Nov 25 to Dec 15. Seed rate: 40-45 kg/acre (timely) and 50-55 kg/acre (late). Line spacing 20 cm at 4-5 cm depth. Nutrient & Fertilizer Schedule (Per Acre):\n- Basal Dose (At Sowing): Apply 55 kg DAP (Diammonium Phosphate) + 25 kg MOP (Muriate of Potash) + 10 kg Zinc Sulfate (21%) + 20 kg Starter Urea drilled below seed depth. - 1st Top Dressing (CRI Stage - 20-22 DAS): Apply 45 kg Urea along with first irrigation.", "source": "Farming Dataset", "page": 8, "topic": "Wheat Agronomy, Crown Root Initiation & Heat Stress", "crop": "Wheat"}, {"id": null, "text": "- 2nd Top Dressing (Late Tillering / Jointing Stage - 40-45 DAS): Apply 45 kg Urea along with second irrigation. - Total Recommended N:P:K: 120:60:40 kg/ha. Avoid late nitrogen application to prevent lodging and foliar rust vulnerability. Critical Irrigation Stages (6 Stage Model):\n1. Crown Root Initiation (CRI) at 20-22 DAS (Most critical; missing this reduces tillers by 30%). 2. Tillering Stage (40-45 DAS). 3. Late Jointing / Stem Elongation (60-65 DAS). 4. Flowering / Booting Stage (80-85 DAS). 5. Milking Stage (100-105 DAS). 6. Dough / Grain Filling (115-120 DAS).", "source": "Farming Dataset", "page": 8, "topic": "Wheat Agronomy, Crown Root Initiation & Heat Stress", "crop": "Wheat"}, {"id": null, "text": "Combating Terminal Heat Stress: Foliar spray of Potassium Nitrate (13-0-45) @ 1% or Salicylic acid (100 ppm) at boot and anthesis stages to preserve flag leaf chlorophyll and grain weight.", "source": "Farming Dataset", "page": 8, "topic": "Wheat Agronomy, Crown Root Initiation & Heat Stress", "crop": "Wheat"}, {"id": null, "text": "PAGE 9: WHEAT PATHOGEN & WEED MANAGEMENT\n1. Yellow / Stripe Rust (Puccinia striiformis): Linear yellow powdery stripes on leaves; thrives in cool humid conditions (<18°C). ETL: 1-2 rusted leaves/m2. Spray Propiconazole 25% EC (Tilt) @ 1 ml/L or Tebuconazole 25.9% EC @ 1.2 ml/L at first appearance. 2. Karnal Bunt (Tilletia indica): Infected grains emit foul fishy odor (trimethylamine). Avoid excessive late irrigation; spray Propiconazole @ 1ml/L at 50% earhead emergence in seed crops. 3.", "source": "Farming Dataset", "page": 9, "topic": "Wheat Yellow Rust, Karnal Bunt & Weed Control", "crop": "Wheat"}, {"id": null, "text": "Complex Weed Management (Phalaris minor & Broadleaf Weeds):\n   - Grassy Weeds (Gullidanda - Phalaris minor): Clodinafop-propargyl 15% WP @ 160g/acre or Pinoxaden 5.1% EC @ 400ml/acre at 30-35 DAS. - Mixed Flora: Sulfosulfuron 75% + Metsulfuron-methyl 5% WG (Total) @ 16g/acre with surfactant at 30-35 DAS. Apply in moist soil with flat-fan nozzle.", "source": "Farming Dataset", "page": 9, "topic": "Wheat Yellow Rust, Karnal Bunt & Weed Control", "crop": "Wheat"}, {"id": null, "text": "PAGE 10: MAIZE (ZEA MAYS) HIGH-YIELD AGRONOMY\nSoil: Deep, well-aerated sandy loam to silt loam with pH 6.0-7.5. Sensitive to water stagnation. Seed Rate & Spacing: 7.5-8 kg/acre of single cross hybrid seed (e.g., DKC-9108, Pioneer 3396) sown @ 60x20 cm. Fertilizer Schedule (Per Acre): Basal: 35 kg DAP + 25 kg MOP + 10 kg Zinc Sulfate. Top Dress 1 (Knee-high 30 DAS): 40 kg Urea. Top Dress 2 (Tasseling/Silking 55 DAS): 35 kg Urea.", "source": "Farming Dataset", "page": 10, "topic": "Maize (Corn) Precision Production & Fall Armyworm", "crop": "Maize (Corn)"}, {"id": null, "text": "Fall Armyworm (Spodoptera frugiperda) Management:\n- Symptoms: Characteristic ragged feeding holes in whorls, sawdust-like fecal matter, inverted 'Y' mark on larval head. - Window 1 (Seedling to V4): Spray Bacillus thuringiensis (Bt) @ 2g/L or Azadirachtin 1500 ppm @ 5ml/L. - Window 2 (V5 to Tasseling - ETL 10% damaged plants): Spray Chlorantraniliprole 18.5% SC @ 0.4 ml/L or Emamectin Benzoate 5% SG @ 0.4 g/L directed into the central leaf whorl.", "source": "Farming Dataset", "page": 10, "topic": "Maize (Corn) Precision Production & Fall Armyworm", "crop": "Maize (Corn)"}, {"id": null, "text": "PAGE 11: COTTON (GOSSYPIUM HIRSUTUM) PRECISION MANAGEMENT\nSoil: Deep black cotton soil (Vertisols) and fertile alluvial loams, pH 6.5-8.0. Spacing: 90x60 cm or 120x45 cm for Bt hybrids. Nutrient Management: N:P:K @ 60:30:30 kg/acre. Apply 25% N + 100% P + 50% K as basal. Remaining N & K split at Square formation and Peak flowering. Apply 10 kg Magnesium Sulfate at 45 DAS to prevent leaf reddening. Pink Bollworm (Pectinophora gossypiella) IPM:\n- Install 5 pheromone traps/acre for surveillance. ETL: 8 moths/trap/night for 3 consecutive days or 10% rosette flowers.", "source": "Farming Dataset", "page": 11, "topic": "Cotton Agronomy, Drip Fertigation & Pink Bollworm", "crop": "Cotton"}, {"id": null, "text": "- Biological Control: Release egg parasitoid Trichogramma bactrae @ 60,000/acre weekly from 45 DAS. - Chemical Control: Spray Profenofos 50% EC @ 2 ml/L or Emamectin Benzoate 5% SG @ 0.4 g/L during active boll formation.", "source": "Farming Dataset", "page": 11, "topic": "Cotton Agronomy, Drip Fertigation & Pink Bollworm", "crop": "Cotton"}, {"id": null, "text": "PAGE 12: SOYBEAN (GLYCINE MAX) PRODUCTION PROTOCOL\nSoil: Well-drained clay loam and medium black soils, pH 6.5-7.5. Avoid waterlogged fields. Sowing & Seed Rate: 25-30 kg/acre (Broad Bed Furrow - BBF planting recommended). Inoculate with Bradyrhizobium japonicum and PSB culture @ 5g/kg seed. Fertilizer Recommendation: N:P:K:S @ 12:24:16:10 kg/acre as basal. Apply Single Super Phosphate (SSP) to satisfy phosphorus and sulfur demands. Pest & Disease Control:\n- Yellow Mosaic Virus (YMV): Transmitted by Whitefly (Bemisia tabaci). Grow resistant varieties (JS-20-29, JS-20-34, NRC-86).", "source": "Farming Dataset", "page": 12, "topic": "Soybean Production, Inoculation & Yellow Mosaic Virus", "crop": "Soybean"}, {"id": null, "text": "Spray Thiamethoxam 25% WG @ 0.3g/L or Acetamiprid 20% SP @ 0.2g/L. - Girdle Beetle (Obereopsis brevis): Ring cutting on petioles and stems. Spray Chlorantraniliprole 18.5% SC @ 0.3ml/L.", "source": "Farming Dataset", "page": 12, "topic": "Soybean Production, Inoculation & Yellow Mosaic Virus", "crop": "Soybean"}, {"id": null, "text": "PAGE 13: GROUNDNUT (ARACHIS HYPOGAEA) AGRONOMY\nSoil: Light, friable sandy loam with loose topsoil for smooth peg penetration, pH 6.0-7.5. Sowing & Spacing: 40-45 kg kernels/acre @ 30x10 cm. Seed treatment with Trichoderma viride (5g/kg) + Imidacloprid (2ml/kg). Critical Gypsum Requirement (Calcium for Pod Filling):\n- Apply 200 kg Agricultural Gypsum (CaSO4.2H2O)/acre at flowering/pegging stage (40-45 DAS) banded along crop rows. Calcium in the pod zone prevents \"pops\" (empty shells) and increases oil content. Tikka Leaf Spot (Cercospora arachidicola): Circular dark spots with yellow halo.", "source": "Farming Dataset", "page": 13, "topic": "Groundnut (Peanut) Pod Formation, Gypsum & Tikka Disease", "crop": "Groundnut"}, {"id": null, "text": "Spray Mancozeb 75% WP @ 2g/L + Carbendazim 50% WP @ 1g/L or Tebuconazole 25.9% EC @ 1.25 ml/L.", "source": "Farming Dataset", "page": 13, "topic": "Groundnut (Peanut) Pod Formation, Gypsum & Tikka Disease", "crop": "Groundnut"}, {"id": null, "text": "PAGE 14: PIGEONPEA (CAJANUS CAJAN) SUSTAINABLE MANAGEMENT\nSoil: Deep well-drained loam and medium black soil, pH 6.5-7.5. Highly sensitive to waterlogging. Intercropping Systems: Pigeonpea + Soybean (1:4 ratio) or Pigeonpea + Cotton (1:1 or 1:2) maximizes land equivalent ratio (LER > 1.3) and risk resilience. Nutrient Application: Basal 10 kg N + 20 kg P2O5 + 10 kg S/acre. Inoculate with Rhizobium. Major Pathogens & Pests:\n1. Fusarium Wilt (Fusarium udum): Vascular browning and sudden wilting.", "source": "Farming Dataset", "page": 14, "topic": "Pigeonpea (Arhar/Tur) Intercropping, Wilt & Pod Borer", "crop": "Pigeonpea (Arhar)"}, {"id": null, "text": "Use wilt-resistant varieties (ICPL-87119 'Asha', BDN-711); apply Trichoderma harzianum @ 2 kg/acre enriched in FYM. 2. Gram Pod Borer (Helicoverpa armigera) & Pod Fly: Install bird perches @ 20/acre; spray Chlorantraniliprole 18.5% SC @ 0.3ml/L or Indoxacarb 14.5% SC @ 1ml/L at 50% flowering.", "source": "Farming Dataset", "page": 14, "topic": "Pigeonpea (Arhar/Tur) Intercropping, Wilt & Pod Borer", "crop": "Pigeonpea (Arhar)"}, {"id": null, "text": "PAGE 15: CHICKPEA (CICER ARIETINUM) PRECISION PROTOCOL\nSoil: Well-drained clay loam to sandy loam, pH 6.0-7.5. Avoid heavy saline soils. Varieties: Desi (JG-11, JAKI-9218, RVG-202) and Kabuli (KAK-2, RVKG-101). Sowing: Mid-October to mid-November. Seed rate: 25-30 kg/acre (Desi) and 35-40 kg/acre (Kabuli) sown at 8-10 cm deep to utilize sub-soil moisture. Irrigation: Rainfed or 1-2 protective irrigations at branching (35-40 DAS) and pod development (65-70 DAS). Avoid irrigation during peak flowering to prevent flower drop.", "source": "Farming Dataset", "page": 15, "topic": "Chickpea (Gram) Moisture Conservation, Sowing & Pod Borer", "crop": "Chickpea (Gram)"}, {"id": null, "text": "Nipping / Topping: Prune top shoot tips at 30-35 DAS to stimulate lateral branch development and increase pod count by 20%.", "source": "Farming Dataset", "page": 15, "topic": "Chickpea (Gram) Moisture Conservation, Sowing & Pod Borer", "crop": "Chickpea (Gram)"}, {"id": null, "text": "PAGE 16: MUSTARD (BRASSICA JUNCEA) OILSEED AGRONOMY\nSoil: Loam to sandy loam, pH 6.0-7.5. Drought and frost hardy. Sowing Window: Oct 1 to Oct 20 for maximum yield and escaping aphid attack. Seed rate: 1.5-2.0 kg/acre @ 30x10 cm spacing. Thinning at 15-20 DAS is mandatory. Fertilizer & Sulfur Requirement: N:P:K:S @ 35:15:15:15 kg/acre. Sulfur application (via SSP or Bentonite Sulfur) directly increases oil content by 2-3%. Mustard Aphid (Lipaphis erysimi) IPM:\n- Sucking insect that colonizes inflorescence during cloudy weather in Jan-Feb.", "source": "Farming Dataset", "page": 16, "topic": "Mustard (Rapeseed) Oil Synthesis, Sowing & Aphid Control", "crop": "Mustard"}, {"id": null, "text": "ETL: 25-30 aphids/10 cm central twig or 1.5 cm aphid colony on 20% plants. - Spray Thiamethoxam 25% WG @ 0.25g/L or Dimethoate 30% EC @ 1.5ml/L in late afternoon hours to protect pollinators.", "source": "Farming Dataset", "page": 16, "topic": "Mustard (Rapeseed) Oil Synthesis, Sowing & Aphid Control", "crop": "Mustard"}, {"id": null, "text": "PAGE 17: POTATO (SOLANUM TUBEROSUM) HIGH-TECH PRODUCTION\nSoil: Friable sandy loam and silt loam rich in organic matter, pH 5.5-6.5. Seed Tuber Quality: Use certified disease-free, well-sprouted tubers (35-50g weight) @ 12-15 quintals/acre. Spacing: 60x20 cm on ridges. Nutrient Schedule: N:P:K @ 75:40:50 kg/acre. Apply 50% N + 100% P + 50% K as basal; balance N & K applied at earthing-up (30-35 DAS).", "source": "Farming Dataset", "page": 17, "topic": "Potato Cultivation, Tuberization, Drip & Late Blight", "crop": "Potato"}, {"id": null, "text": "Late Blight (Phytophthora infestans) Epidemic Management:\n- Water-soaked dark lesions with white fungal down on lower leaf surface; destroys canopy in 48-72 hours under cool foggy conditions (12-18°C, RH > 90%). - Prophylactic spray: Mancozeb 75% WP @ 2.5g/L or Chlorothalonil 75% WP @ 2g/L before canopy closure. - Curative intervention: Cymoxanil 8% + Mancozeb 64% WP @ 2.5g/L or Dimethomorph 50% WP @ 1g/L.", "source": "Farming Dataset", "page": 17, "topic": "Potato Cultivation, Tuberization, Drip & Late Blight", "crop": "Potato"}, {"id": null, "text": "PAGE 18: TOMATO (SOLANUM LYCOPERSICUM) COMMERCIAL PROTOCOLS\nSoil: Sandy loam to clay loam rich in organic matter, pH 6.0-7.0. Transplanting & Trellising: 25-day seedlings planted on raised beds with drip irrigation and silver-black plastic mulch (25 micron). Indeterminate varieties require bamboo staking or wire trellising. Drip Fertigation Schedule (Weekly per Acre):\n- Vegetative (1-4 weeks): 19-19-19 @ 3 kg/week. - Flowering (5-8 weeks): 12-61-00 (MAP) @ 3 kg + Calcium Nitrate @ 2.5 kg/week. - Fruiting & Harvesting: 0-0-50 (SOP) @ 4 kg + 13-0-45 @ 3 kg/week.", "source": "Farming Dataset", "page": 18, "topic": "Tomato Drip Fertigation, Staking & Blossom End Rot", "crop": "Tomato"}, {"id": null, "text": "Blossom End Rot Prevention: Physiological disorder caused by localized Calcium deficiency and moisture fluctuations. Spray Calcium Chloride (0.5%) + Boron (0.1%) during early fruit set.", "source": "Farming Dataset", "page": 18, "topic": "Tomato Drip Fertigation, Staking & Blossom End Rot", "crop": "Tomato"}, {"id": null, "text": "PAGE 19: CHILLI (CAPSICUM ANNUUM) CROP MANAGEMENT\nSoil: Well-drained light to medium loam with high organic carbon, pH 6.5-7.5. Nursery & Transplanting: Raised beds under 40-mesh shade net; transplant at 35-40 days @ 60x45 cm. Major Pest: Invasive Black Thrips (Thrips parvispinus) & Yellow Mites:\n- Causes upward leaf curling, flower drop, and fruit scarring. Install 20 blue and yellow sticky traps/acre. - Chemical Management: Spray Spinetoram 11.7% SC @ 1 ml/L or Fipronil 5% SC @ 2 ml/L or Broflanilide 300 SC @ 0.15 ml/L.", "source": "Farming Dataset", "page": 19, "topic": "Chilli Precision Cultivation, Thrips & Anthracnose", "crop": "Chilli"}, {"id": null, "text": "Anthracnose / Die-back (Colletotrichum capsici): Circular sunken necrotic spots on ripe pods. Spray Azoxystrobin 23% SC @ 1 ml/L or Difenoconazole 25% EC @ 0.5 ml/L.", "source": "Farming Dataset", "page": 19, "topic": "Chilli Precision Cultivation, Thrips & Anthracnose", "crop": "Chilli"}, {"id": null, "text": "PAGE 20: BRINJAL (SOLANUM MELONGENA) AGRONOMY\nSoil: Silt loam and clay loam with good drainage, pH 6.0-7.0. Spacing: 75x60 cm for bushy hybrids. Nutrient Management: N:P:K @ 50:30:25 kg/acre in 3 splits. Shoot and Fruit Borer (Leucinodes orbonalis) IPM:\n- Larvae bore into tender shoots (causing drooping shoots) and fruits (making them unmarketable). - Install Leucinodes pheromone traps @ 10/acre. - Clip and destroy withered drooping shoots weekly along with boring larvae. - Spray Emamectin Benzoate 5% SG @ 0.4 g/L or Chlorantraniliprole 18.5% SC @ 0.4 ml/L or Flubendiamide 39.35% SC @ 0.5 ml/L.", "source": "Farming Dataset", "page": 20, "topic": "Brinjal (Eggplant) Production & Shoot/Fruit Borer", "crop": "Brinjal"}, {"id": null, "text": "PAGE 21: PRECISION AGRICULTURE & SMART FARMING FRAMEWORK\nDefinition & Core Principles: Precision Agriculture (Smart Farming) is a data-driven farming management concept that uses digital technologies to observe, measure, and respond to spatial and temporal field variability, ensuring that crops receive exactly the inputs (water, nutrients, protection) required for maximum yield and sustainability. Key Pillars & Technologies of Precision Farming:\n1.", "source": "Farming Dataset", "page": 21, "topic": "Precision Agriculture, Smart Farming Technologies & IoT Integration", "crop": "General"}, {"id": null, "text": "Precision Drip & Micro-Irrigation: Sensor-guided drip systems and automated solenoid valves delivering precise water volume directly to crop roots, conserving 40-60% water. 2. Variable Rate Application (VRA): Dynamic rate adjustment of fertilizers and seeds based on soil fertility grid mapping and satellite NDVI prescription zones. 3. Drone Remote Sensing & Ultra-Low Volume Spraying: DGCA-certified UAV drones equipped with multispectral cameras and rotary atomizers for 10 L/acre precision spraying. 4.", "source": "Farming Dataset", "page": 21, "topic": "Precision Agriculture, Smart Farming Technologies & IoT Integration", "crop": "General"}, {"id": null, "text": "IoT Soil & Weather Telemetry: Wireless capacitance probes and automated weather stations (AWS) monitoring soil moisture tension, ambient temperature, and leaf wetness. 5. Automated Drip Fertigation: Injecting 100% water-soluble fertilizers in sync with daily crop uptake curves, increasing Nutrient Use Efficiency (NUE) from 35% to 80%. 6. Computer Vision Pathology: Deep learning models (CNNs/Vision Transformers) for real-time field disease diagnosis and weed spot-spraying.", "source": "Farming Dataset", "page": 21, "topic": "Precision Agriculture, Smart Farming Technologies & IoT Integration", "crop": "General"}, {"id": null, "text": "PAGE 22: AUTOMATED FERTIGATION & NUTRIENT INJECTION\nFertigation delivers 100% water-soluble fertilizers (WSF) directly to the active root zone in synchronization with crop uptake curves. Nutrient Uptake Efficiency (NUE): Increases Nitrogen efficiency from 35% to 75%, and Potassium efficiency from 50% to 85%. Standard Compatibility Matrix (Avoid Precipitates):\n- Tank A: Calcium Nitrate + Potassium Nitrate + Iron EDTA. - Tank B: Monoammonium Phosphate (MAP 12-61-00) + Potassium Sulfate (SOP 0-0-50) + Magnesium Sulfate + Micronutrients.", "source": "Farming Dataset", "page": 22, "topic": "Automated Fertigation & Water-Soluble Fertilizers", "crop": "General"}, {"id": null, "text": "- Rule: NEVER mix Calcium fertilizers with Phosphates or Sulfates in the same concentrated stock solution tank as insoluble Calcium Phosphate / Gypsum will form and clog drippers. Automation Levels: Time-based solenoid valve controllers vs Volume-based vs Soil Moisture Sensor feedback loops.", "source": "Farming Dataset", "page": 22, "topic": "Automated Fertigation & Water-Soluble Fertilizers", "crop": "General"}, {"id": null, "text": "PAGE 23: SOIL MOISTURE SENSORS & IRRIGATION AUTOMATION\nSensor Technologies:\n1. Volumetric Water Content (VWC) Capacitance Probes: Measure dielectric permittivity across soil depths (e.g. 15 cm, 30 cm, 60 cm). Provides continuous % volumetric moisture data via LoRaWAN / GSM telemetry. 2. Soil Water Potential (Tensiometers & Watermark Granular Matrix): Measure matric suction tension in centibars (cb) or kPa. * Field Capacity: 10-25 cb (Ideal for most crops). * Irrigation Trigger Point: 40-50 cb (Vegetables/Fruits); 60-70 cb (Field crops). * Permanent Wilting Point: > 150 cb.", "source": "Farming Dataset", "page": 23, "topic": "Soil Moisture Sensors, Capacitance Probes & Tensiometers", "crop": "General"}, {"id": null, "text": "Placement Strategy: Install probes within the active root bulb (15-20 cm from plant base, between two drippers). Ensure firm soil contact without air pockets.", "source": "Farming Dataset", "page": 23, "topic": "Soil Moisture Sensors, Capacitance Probes & Tensiometers", "crop": "General"}, {"id": null, "text": "PAGE 24: ON-FARM AUTOMATED WEATHER STATIONS (AWS)\nComponents: Solar-powered mast equipped with Ultrasonic Anemometer (Wind Speed/Direction), Tipping Bucket Rain Gauge, Pyranometer (Solar Radiation), Ambient Temperature & Relative Humidity sensors, and Leaf Wetness Sensor. Key Calculations Derived:\n1. Reference Evapotranspiration (ET0 - FAO-56 Penman-Monteith equation): Calculates daily water loss in mm/day. Crop Water Need (ETc) = ET0 x Kc (Crop Coefficient). 2.", "source": "Farming Dataset", "page": 24, "topic": "Automated Weather Stations (AWS) & IoT Microclimate Sensing", "crop": "General"}, {"id": null, "text": "Disease Epidemic Forecasting: Leaf wetness duration + canopy temperature models forecast Late Blight in Potato, Rust in Wheat, and Blast in Rice 48-72 hours before visible symptoms. 3. Frost and Heatwave Early Warnings: Triggers automated sprinkler misting or protective foliar sprays.", "source": "Farming Dataset", "page": 24, "topic": "Automated Weather Stations (AWS) & IoT Microclimate Sensing", "crop": "General"}, {"id": null, "text": "PAGE 25: AGRICULTURAL DRONES (UAVS) IN MODERN FARMING\n1. Drone Spraying Systems (10L - 30L Payload):\n   - Ultra-Low Volume (ULV) Rotary Atomizers produce uniform droplet spectra (100-200 microns). - Rotor Downwash Turbulence penetrates thick crop canopies (Paddy, Sugarcane, Cotton), coating both upper and lower leaf surfaces. - Efficiency: Covers 1 acre in 6-8 minutes with 90% water reduction (10 liters water/acre vs 150-200 liters manual). 2.", "source": "Farming Dataset", "page": 25, "topic": "Agricultural Drones (UAVs) for Spraying & Multispectral Imaging", "crop": "General"}, {"id": null, "text": "Multispectral Drone Sensing:\n   - Captures Red, Green, Blue, Red-Edge, and Near-Infrared (NIR) bands to generate sub-centimeter Normalized Difference Vegetation Index (NDVI) and NDRE maps. - Pinpoints nitrogen deficiency, nematode patches, and water stress zones for spot treatment. Operational Safety: Maintain 2-3 meter spray height above canopy; avoid drone operations during high winds (>15 km/h) or temperatures >35°C.", "source": "Farming Dataset", "page": 25, "topic": "Agricultural Drones (UAVs) for Spraying & Multispectral Imaging", "crop": "General"}, {"id": null, "text": "PAGE 26: SATELLITE REMOTE SENSING & GIS ANALYTICS\nConstellations Used: Sentinel-2 (10m multispectral, 5-day revisit), Landsat-9 (30m), and commercial high-resolution PlanetScope (3m daily). Key Vegetation Indices:\n1. Normalized Difference Vegetation Index (NDVI = (NIR - Red) / (NIR + Red)): Values 0.2-0.4 (sparse/stressed canopy); 0.6-0.85 (dense, healthy vegetative growth). 2. Normalized Difference Water Index (NDWI): Evaluates canopy moisture status and drought stress. 3. Enhanced Vegetation Index (EVI): Corrects for atmospheric aerosols and soil background in high-biomass crops.", "source": "Farming Dataset", "page": 26, "topic": "Satellite Remote Sensing, NDVI & GIS Precision Mapping", "crop": "General"}, {"id": null, "text": "Applications: Regional crop acreage estimation, crop insurance yield assessment under PMFBY, and historical zone delineation for Variable Rate Application (VRA).", "source": "Farming Dataset", "page": 26, "topic": "Satellite Remote Sensing, NDVI & GIS Precision Mapping", "crop": "General"}, {"id": null, "text": "PAGE 27: COMPUTER VISION & ARTIFICIAL INTELLIGENCE\nAI & Machine Learning Architectures in Smart Farming:\n1. Deep Learning Foliar Pathology: Convolutional Neural Networks (ResNet-50, EfficientNet-B4, Vision Transformers) trained on 100,000+ field images classify 80+ crop diseases with >92% accuracy from smartphone photos. 2. Edge AI Camera Traps: Smart solar-powered optical traps with onboard YOLOv8 models count and classify insect pests (Pink Bollworm, Helicoverpa, Spodoptera) in real-time. 3.", "source": "Farming Dataset", "page": 27, "topic": "Computer Vision & AI/ML in Agriculture", "crop": "General"}, {"id": null, "text": "Yield Estimation Models: Combining satellite NDVI time-series, weather indices (GDD - Growing Degree Days), and soil test parameters using Random Forest and XGBoost regression to predict harvest yields 30 days in advance. 4. Smart Weed Spot-Spraying: Tractor-mounted high-speed cameras distinguish broadleaf weeds from crop plants and trigger micro-solenoids for 80% herbicide reduction.", "source": "Farming Dataset", "page": 27, "topic": "Computer Vision & AI/ML in Agriculture", "crop": "General"}, {"id": null, "text": "PAGE 28: PROTECTED CULTIVATION & HYDROPONICS\n1. Climate-Controlled Polyhouses (Naturally Ventilated vs Fan-Pad Evaporative):\n   - Protects high-value crops (Colored Capsicum, Dutch Cucumber, Cherry Tomato, Orchids) from unseasonal rains, hail, and viral insect vectors. - Microclimate Control: Shading nets (50%), motorized thermal screens, and fogging nozzles maintain 24-28°C and 65-75% RH. - Productivity: 4-6x higher yield per unit area with 90% A-grade export quality produce. 2. Commercial Hydroponic Systems:\n   - Nutrient Film Technique (NFT) for leafy greens (Lettuce, Spinach, Herbs).", "source": "Farming Dataset", "page": 28, "topic": "Greenhouse, Polyhouse & Hydroponic Controlled Agriculture", "crop": "Horticulture"}, {"id": null, "text": "- Dutch Bucket Bato System using Cocopeat/Perlite substrate for indeterminate vine tomatoes and cucumbers. - Closed-loop recirculation recycles 95% water and nutrients with zero soil-borne pathogens.", "source": "Farming Dataset", "page": 28, "topic": "Greenhouse, Polyhouse & Hydroponic Controlled Agriculture", "crop": "Horticulture"}, {"id": null, "text": "PAGE 29: SOLAR IRRIGATION & PM-KUSUM SCHEME\nSolar Pumping Architecture: Photovoltaic (PV) array (3 HP to 10 HP) connected to a Variable Frequency Drive (VFD) Solar Pump Inverter driving a Submersible DC/AC pump. Integration with Drip Systems: VFD automatically modulates pump RPM based on solar irradiance, maintaining steady pressure and discharge across drip laterals without battery storage. Government Subsidies under PM-KUSUM:\n- Component B: Up to 60% capital subsidy (30% Central + 30% State) for standalone solar agricultural pumps for individual farmers in off-grid zones.", "source": "Farming Dataset", "page": 29, "topic": "Solar Powered Micro-Irrigation & Decentralized Pumping", "crop": "General"}, {"id": null, "text": "- Component C: Solarization of existing grid-connected agriculture pumps with net-metering to sell surplus power to local DISCOMs. Payback Period: 2.5 to 3.5 years considering diesel replacement savings and grid independence.", "source": "Farming Dataset", "page": 29, "topic": "Solar Powered Micro-Irrigation & Decentralized Pumping", "crop": "General"}, {"id": null, "text": "PAGE 30: SMART STORAGE, COLD CHAIN & POST-HARVEST IOT\nLoss Prevention: India experiences 15-25% post-harvest loss in perishables (Fruits & Vegetables) and 6-10% in foodgrains. Modern Smart Storage Technologies:\n1. IoT-Monitored Grain Silos: Hermetic steel silos fitted with multi-depth temperature and moisture cable sensors detect fungal \"hotspots\" and carbon dioxide spikes, automatically triggering aeration fans. 2.", "source": "Farming Dataset", "page": 30, "topic": "Smart Post-Harvest Storage, Cold Chain & IoT Silos", "crop": "General"}, {"id": null, "text": "Controlled Atmosphere (CA) Cold Storage: Regulates Oxygen (1.5-2.0%), Carbon Dioxide (1.0-2.0%), Temperature (0-2°C), and 95% RH to store Apples, Potatoes, and Pears for up to 9-11 months. 3. Solar-Powered Micro Cold Rooms (5-10 MT): Installed at farm-gate / FPO level with thermal phase change material (PCM) backup for 24-hour cooling during grid outages.", "source": "Farming Dataset", "page": 30, "topic": "Smart Post-Harvest Storage, Cold Chain & IoT Silos", "crop": "General"}, {"id": null, "text": "PAGE 31: BENEFITS OF MODERN FARMING & AGRITECH ADOPTION\nKey Benefits of Modern Farming Technologies:\n1. Significant Resource Efficiency: Precision drip irrigation and soil IoT sensors reduce agricultural water consumption by 40-60% while automated fertigation increases nutrient use efficiency (NUE) from 35% to 80%. 2. Substantial Yield & Productivity Gains: Controlled environment polyhouses, high-vigor certified seeds, and balanced fertigation protocols deliver 20-35% higher harvest yields with 90% export-grade produce quality. 3.", "source": "Farming Dataset", "page": 31, "topic": "Benefits of Modern Farming, Agritech Adoption & ROI", "crop": "General"}, {"id": null, "text": "Lower Production Costs & Labor Savings: Variable Rate Application (VRA) and drone ultra-low volume (ULV) spraying cut chemical and fertilizer input expenditures by 20-30%, spraying 1 acre in just 6-8 minutes. 4. Early Risk Detection & Crop Protection: Multispectral UAV imaging and satellite NDVI mapping detect crop canopy moisture stress, chlorophyll chlorosis, and pest hotspots 7-10 days before visible symptoms occur. 5.", "source": "Farming Dataset", "page": 31, "topic": "Benefits of Modern Farming, Agritech Adoption & ROI", "crop": "General"}, {"id": null, "text": "Climate Resilience & Financial Sustainability: Solar-powered micro-irrigation systems under PM-KUSUM eliminate fossil diesel costs, achieve financial payback in 2.5 to 3.5 years, and provide reliable year-round irrigation.", "source": "Farming Dataset", "page": 31, "topic": "Benefits of Modern Farming, Agritech Adoption & ROI", "crop": "General"}, {"id": null, "text": "Indicative Capital Expenditures & Financial Paybacks in India:\n1. Drip Irrigation System (1 Acre): Rs 45,000 - 65,000 gross cost (Net farmer share Rs 22,000 - 30,000 with 45-55% PMKSY subsidy). Payback: 1 season through 30% yield boost and 40% fertilizer savings. 2. Soil Moisture IoT Probe & Telemetry Station: Rs 18,000 - 35,000. Payback: 1-2 years via power and water conservation. 3. Naturally Ventilated Polyhouse (1000 sq.m / 0.25 Acre): Rs 9.5 - 12.5 Lakhs gross cost (50% NHB / State Horticulture Subsidy). Net farmer investment ~Rs 5-6 Lakhs. Annual net profit Rs 2.5 - 4 Lakhs.", "source": "Farming Dataset", "page": 31, "topic": "Benefits of Modern Farming, Agritech Adoption & ROI", "crop": "General"}, {"id": null, "text": "Payback: 2.5 - 3 years. 4. Custom Hiring Centers (CHC) for Drones: Rs 6-8 Lakhs per certified DGCA drone. Supported with up to 40-50% SMAM subsidy.", "source": "Farming Dataset", "page": 31, "topic": "Benefits of Modern Farming, Agritech Adoption & ROI", "crop": "General"}, {"id": null, "text": "PAGE 32: TECHNOLOGY LIMITATIONS, CONNECTIVITY & FAILURE MODES\nKey Implementation Risks & Mitigation:\n1. Sensor Drift & Bio-Fouling: Capacitance soil moisture sensors drift over time due to soil settlement and root entanglement. Annual recalibration and cleaning are mandatory. 2. Rural Connectivity & Telemetry Outages: GSM 4G coverage can be intermittent in deep rural agricultural fields. Deploy LoRaWAN gateways with local edge SD-card buffering to prevent data loss. 3. High Power Grid Surges: Unregulated rural power swings damage pump inverters and automated fertigation controllers.", "source": "Farming Dataset", "page": 32, "topic": "Agritech Limitations, Connectivity Risks & Maintenance", "crop": "General"}, {"id": null, "text": "Install heavy-duty surge protection devices (SPD) and voltage stabilizers. 4. Battery Lifecycle in IoT Hardware: Solar-rechargeable LiFePO4 batteries last 4-5 years compared to standard Lead-Acid (1.5 years) in harsh Indian summer ambient temperatures (45°C+).", "source": "Farming Dataset", "page": 32, "topic": "Agritech Limitations, Connectivity Risks & Maintenance", "crop": "General"}, {"id": null, "text": "1. WHEAT IPM STRATEGIES\n- Yellow Rust (Puccinia striiformis): Characterized by linear yellow pustules along leaf veins forming stripes. Most severe in cool, humid sub-montane conditions. Economic threshold level (ETL): 1-2 rusted leaves per square meter. Chemical intervention: Propiconazole 25% EC (Tilt) @ 1 ml/L or Tebuconazole 25.9% EC @ 1.25 ml/L on initial symptom appearance. - Karnal Bunt (Tilletia indica): Infected grains converted into black powdery mass with fishy odor (trimethylamine). Sowing before Nov 25 and avoiding excessive late irrigations during flowering reduces incidence.", "source": "integrated_pest_management_wheat_cotton.txt", "page": 1, "topic": "", "crop": "Wheat, Cotton, Chickpea"}, {"id": null, "text": "- Aphids (Rhopalosiphum padi): Suck sap from leaves and earheads. ETL: 5 aphids per earhead. Spray Thiamethoxam 25% WG @ 0.25 g/L or Imidacloprid 17.8% SL @ 0.3 ml/L.", "source": "integrated_pest_management_wheat_cotton.txt", "page": 1, "topic": "", "crop": "Wheat, Cotton, Chickpea"}, {"id": null, "text": "2. COTTON INTEGRATED PEST MANAGEMENT\n- Pink Bollworm (Pectinophora gossypiella): Larvae bore into bolls, creating rosette flowers and stained lint. ETL: 8 moths per pheromone trap per night for 3 consecutive nights, or 10% damaged green bolls. Biological management: Install 5 pheromone traps/acre and release Trichogramma bactrae @ 60,000 parasitized eggs/acre weekly. Chemical control: Emamectin Benzoate 5% SG @ 0.4 g/L or Profenofos 50% EC @ 2 ml/L. - Whitefly (Bemisia tabaci): Vector for Cotton Leaf Curl Virus (CLCuV). ETL: 6-8 nymphs/adults per leaf.", "source": "integrated_pest_management_wheat_cotton.txt", "page": 1, "topic": "", "crop": "Wheat, Cotton, Chickpea"}, {"id": null, "text": "Spray Pyriproxyfen 10% EC @ 2 ml/L or Diafenthiuron 50% WP @ 1.2 g/L.", "source": "integrated_pest_management_wheat_cotton.txt", "page": 1, "topic": "", "crop": "Wheat, Cotton, Chickpea"}, {"id": null, "text": "3. CHICKPEA (GRAM) POD BORER MANAGEMENT\n- Gram Pod Borer (Helicoverpa armigera): Larvae feed on leaves and bore into developing pods with body halfway outside. ETL: 1-2 larvae per meter row length.\n- Intercrop with Coriander or Mustard as trap crop; install bird perches @ 20/acre.\n- Bio-pesticides: Spray NPV (Nuclear Polyhedrosis Virus) @ 250 LE/acre or Bacillus thuringiensis (Bt) @ 1.5 g/L.\n- Chemical control: Chlorantraniliprole 18.5% SC (Coragen) @ 0.3 ml/L or Indoxacarb 14.5% SC @ 1 ml/L.", "source": "integrated_pest_management_wheat_cotton.txt", "page": 1, "topic": "", "crop": "Wheat, Cotton, Chickpea"}, {"id": null, "text": "Scheme_Name: PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) | Category: Direct Income Support | Target_Audience: All landholding farmers | Financial_Assistance: Rs. 6000 per year in three equal 4-monthly installments of Rs. 2000 each | Eligibility_Criteria: Small & marginal farmer families owning cultivable land; excluded if institutional landholders or income tax payees | Application_Procedure: Online portal pmkisan.gov.in or CSC centers with Aadhaar and land record verification | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 1, "topic": "", "crop": "General"}, {"id": null, "text": "Scheme_Name: PM Fasal Bima Yojana (PMFBY) | Category: Crop Insurance | Target_Audience: Farmers cultivating notified crops | Financial_Assistance: Comprehensive risk coverage for yield losses due to non-preventable natural risks (drought flood pests); Farmer premium only 2% for Kharif 1.5% for Rabi and 5% for commercial/horticultural crops | Eligibility_Criteria: All farmers including sharecroppers and tenant farmers growing notified crops in notified areas | Application_Procedure: Through National Crop Insurance Portal (NCIP) or local banks before sowing cut-off date | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 2, "topic": "", "crop": "General"}, {"id": null, "text": "Scheme_Name: Sub-Mission on Agricultural Mechanization (SMAM) | Category: Farm Machinery Subsidy | Target_Audience: Small marginal SC/ST and women farmers | Financial_Assistance: 40% to 50% subsidy on procurement of tractors rotavators laser land levelers combine harvesters and drone sprayers; up to 80% for Custom Hiring Centers | Eligibility_Criteria: Individual farmers and Farmer Producer Organizations (FPOs) with verified landholding | Application_Procedure: Direct Benefit Transfer (DBT) portal on agrimachinery.nic.in | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 3, "topic": "", "crop": "General"}, {"id": null, "text": "Scheme_Name: Soil Health Card Scheme (SHC) | Category: Soil Testing & Nutrition | Target_Audience: All active farmers | Financial_Assistance: Free comprehensive soil testing every 2 years with crop-wise nutrient recommendations and soil health card issuance | Eligibility_Criteria: All agricultural landholders across all districts | Application_Procedure: State agricultural department soil testing labs and Krishi Vigyan Kendras (KVK) | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 4, "topic": "", "crop": "General"}, {"id": null, "text": "Scheme_Name: Pradhan Mantri Krishi Sinchayee Yojana (PMKSY) - Per Drop More Crop | Category: Micro Irrigation | Target_Audience: Irrigated & rainfed farmers | Financial_Assistance: Up to 55% subsidy for small and marginal farmers (45% for other farmers) for installation of drip and sprinkler irrigation systems | Eligibility_Criteria: Farmers with cultivable land and assured water source for drip/sprinkler installation | Application_Procedure: State horticulture and agriculture portals or district agriculture officer | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 5, "topic": "", "crop": "General"}, {"id": null, "text": "Scheme_Name: Agriculture Infrastructure Fund (AIF) | Category: Post-Harvest Infrastructure | Target_Audience: Agri-entrepreneurs FPOs Cooperatives and Startups | Financial_Assistance: Medium to long term debt financing facility with 3% per annum interest subvention up to Rs. 2 Crore loan and CGTMSE fee coverage | Eligibility_Criteria: Primary Agricultural Credit Societies (PACS) FPOs SHGs and Agri-entrepreneurs setting up cold storage warehouses and primary processing | Application_Procedure: Online application via agriinfra.dac.gov.in | Geography: Pan-India | Year: 2024", "source": "pm_kisan_and_government_schemes.csv", "page": 6, "topic": "", "crop": "General"}, {"id": null, "text": "1. FIELD PREPARATION & SOWING\nPaddy requires well-levelled, puddled clay or clay-loam soils with high water retention capacity.\n- Nursery Sowing Time: May 20 to June 15 for nursery raising; transplanting 25-30 days after sowing.\n- Seed Rate: 8-10 kg/acre for short/medium varieties; 5-6 kg/acre for basmati varieties.\n- Seed Treatment: Treat seeds with Carbendazim (2g/kg) or Trichoderma viride (5g/kg) to prevent blast and foot-rot.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "2. WATER MANAGEMENT & IRRIGATION\n- Transplanting to Tillering Stage: Maintain shallow standing water depth of 2-3 cm for the first 15 days to suppress weed emergence. - Tillering to Panicle Initiation: Alternate Wetting and Drying (AWD) is recommended. Irrigate 2-3 days after ponded water has disappeared to conserve up to 30% irrigation water without reducing yield. - Flowering & Grain Filling: Maintain continuous submergence of 3-5 cm. Water stress during anthesis causes sterility and high chaff percentage.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "- Pre-Harvest Drainage: Drain water 10-12 days before anticipated harvest to facilitate mechanized combine harvesting.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "3. NUTRIENT & FERTILIZER SCHEDULE (Per Acre Recommendation)\n- Basal Dose (At Transplanting): 25 kg DAP (Diammonium Phosphate) + 20 kg MOP (Muriate of Potash) + 10 kg Zinc Sulfate (21% Zn).\n- First Top Dressing (21 Days After Transplanting / Active Tillering): 35 kg Urea.\n- Second Top Dressing (42-45 Days After Transplanting / Panicle Initiation): 35 kg Urea.\n- Note: Avoid excessive nitrogen (>120 kg N/ha) which predisposes the canopy to Brown Plant Hopper (BPH) and Bacterial Leaf Blight.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "4. DISEASE & PEST MANAGEMENT\n- Rice Blast (Magnaporthe oryzae): Symptoms include spindle-shaped lesions on leaves with brown borders and grey centers. Spray Tricyclazole 75% WP @ 0.6g/L or Isoprothiolane 40% EC @ 1.5 ml/L. - Sheath Blight (Rhizoctonia solani): Oval grayish-green lesions on leaf sheaths near water line. Apply Hexaconazole 5% SC @ 2 ml/L or Azoxystrobin 18.2% + Difenoconazole 11.4% SC @ 1 ml/L. - Brown Plant Hopper (Nilaparvata lugens): Causes \"hopper burn\" circular drying patches in dense foliage. Use Pymetrozine 50% WDG @ 0.6g/L or Triflumezopyrim 10% SC @ 0.5 ml/L.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "- Stem Borer (Scirpophaga incertulas): Produces \"dead hearts\" in vegetative stage and \"white ears\" in reproductive stage. Apply Chlorantraniliprole 0.4% GR @ 4 kg/acre.", "source": "rice_cultivation_guide.txt", "page": 1, "topic": "", "crop": "Rice (Paddy)"}, {"id": null, "text": "========================================================================\nKRISHI VIGYAN KENDRA SOIL HEALTH TESTING LABORATORY\nSOIL TEST CERTIFICATE & NUTRIENT STATUS REPORT\n========================================================================\nFarmer Name: Santosh Jadhav\nLocation: Nashik, Maharashtra\nSoil Type: Medium Black Soil (Vertisol)\nSample ID: MH-NSK-2024-8841\nDate of Testing: 15-Oct-2024", "source": "sample_soil_report_maharashtra.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "LABORATORY TEST RESULTS:\n------------------------------------------------------------------------\nParameter                  Value         Unit        Rating\n------------------------------------------------------------------------\nSoil Reaction (pH)         6.80          pH units    Neutral / Optimal\nElectrical Cond (EC)       0.31          dS/m        Normal\nOrganic Carbon (OC)        0.65          %           Medium\nAvailable Nitrogen (N)     260.0         kg/ha       Low\nAvailable Phosphorus (P)   34.5          kg/ha       Medium\nAvailable Potassium (K)    220.0         kg/ha       Medium\nZinc (DTPA extractable)    0.85          ppm         Sufficient\nIron (DTPA extractable)    6.10          ppm         Sufficient\nBoron                      0.55          ppm         Sufficient\nSulfur (S)                 14.2          ppm         Sufficient\n========================================================================\nAGRONOMIST SUMMARY:\nSoil pH and micronutrients are well balanced.", "source": "sample_soil_report_maharashtra.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "Available Nitrogen is deficient. Recommended base application of 4 tonnes Farm Yard Manure plus standard NPK dose with a 15% increase in starter nitrogen. ========================================================================", "source": "sample_soil_report_maharashtra.txt", "page": 1, "topic": "", "crop": ""}, {"id": null, "text": "Parameter: Soil pH | Measured_Value: 7.8 | Unit: pH scale | Benchmark_Status: Slightly Alkaline | Standard_Range: 6.5 - 7.5", "source": "sample_soil_report_punjab.csv", "page": 1, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Electrical Conductivity (EC) | Measured_Value: 0.42 | Unit: dS/m | Benchmark_Status: Normal | Standard_Range: < 1.0", "source": "sample_soil_report_punjab.csv", "page": 2, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Organic Carbon (OC) | Measured_Value: 0.41 | Unit: % | Benchmark_Status: Low | Standard_Range: 0.50 - 0.75", "source": "sample_soil_report_punjab.csv", "page": 3, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Nitrogen (N) | Measured_Value: 210.5 | Unit: kg/ha | Benchmark_Status: Low | Standard_Range: 280 - 560", "source": "sample_soil_report_punjab.csv", "page": 4, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Phosphorus (P2O5) | Measured_Value: 18.2 | Unit: kg/ha | Benchmark_Status: Low | Standard_Range: 23 - 56", "source": "sample_soil_report_punjab.csv", "page": 5, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Potassium (K2O) | Measured_Value: 310.0 | Unit: kg/ha | Benchmark_Status: High | Standard_Range: 140 - 280", "source": "sample_soil_report_punjab.csv", "page": 6, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Zinc (Zn) | Measured_Value: 0.48 | Unit: ppm | Benchmark_Status: Deficient | Standard_Range: 0.6 - 1.2", "source": "sample_soil_report_punjab.csv", "page": 7, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Iron (Fe) | Measured_Value: 5.20 | Unit: ppm | Benchmark_Status: Sufficient | Standard_Range: 4.5 - 9.0", "source": "sample_soil_report_punjab.csv", "page": 8, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Boron (B) | Measured_Value: 0.38 | Unit: ppm | Benchmark_Status: Deficient | Standard_Range: 0.5 - 1.0", "source": "sample_soil_report_punjab.csv", "page": 9, "topic": "", "crop": "General"}, {"id": null, "text": "Parameter: Available Sulfur (S) | Measured_Value: 8.40 | Unit: ppm | Benchmark_Status: Deficient | Standard_Range: 10.0 - 20.0", "source": "sample_soil_report_punjab.csv", "page": 10, "topic": "", "crop": "General"}, {"id": null, "text": "1. SOIL TEST PARAMETERS & INTERPRETATION BENCHMARKS\nA complete soil health analysis examines chemical, physical, and biological fertility indices:\n\n- Soil Reaction (pH):\n  * Acidic: pH < 6.5 (Requires agricultural lime/calcite CaCo3 application @ 1-2 tons/ha)\n  * Optimal / Neutral: pH 6.5 - 7.5 (Maximum availability of macronutrients and trace elements)\n  * Alkaline / Sodic: pH > 8.2 (Requires agricultural Gypsum CaSO4.2H2O application + green manuring)", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}, {"id": null, "text": "- Electrical Conductivity (EC - Salinity in dS/m):\n  * Normal: < 1.0 dS/m\n  * Critical / Saline stress: > 2.0 dS/m (Leaching with good quality water required)\n\n- Organic Carbon (OC %):\n  * Low: < 0.50% (Depleted soil biology; apply 5-10 tonnes/acre Farm Yard Manure (FYM) or vermicompost)\n  * Medium: 0.50% - 0.75%\n  * High: > 0.75% (Excellent organic microbial activity and cation exchange capacity)", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}, {"id": null, "text": "- Available Nitrogen (N in kg/ha):\n  * Low: < 280 kg/ha (Requires 25% boost in basal and split nitrogen doses)\n  * Medium: 280 - 560 kg/ha (Apply standard recommended dose of fertilizer)\n  * High: > 560 kg/ha (Reduce nitrogen input by 20% to avoid lodging and pest outbreak)\n\n- Available Phosphorus (P2O5 in kg/ha):\n  * Low: < 23 kg/ha (Apply Single Super Phosphate (SSP) or DAP with mycorrhiza biofertilizer)\n  * Medium: 23 - 56 kg/ha\n  * High: > 56 kg/ha", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}, {"id": null, "text": "- Available Potassium (K2O in kg/ha):\n  * Low: < 140 kg/ha (Apply Muriate of Potash (MOP) or Sulfate of Potash (SOP))\n  * Medium: 140 - 280 kg/ha\n  * High: > 280 kg/ha", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}, {"id": null, "text": "- Micronutrients (Zinc, Iron, Boron, Sulfur):\n  * Zinc (DTPA extractable): Critical level is 0.6 ppm. Deficient soils require 10-15 kg Zinc Sulfate/acre.\n  * Iron: Critical level is 4.5 ppm. In calcareous soils, foliar spray of 0.5% FeSO4 is recommended.\n  * Boron: Critical level is 0.5 ppm. Deficiency causes hollow heart in potato and fruit cracking in tomato. Apply 2-3 kg Borax/acre.\n  * Sulfur: Critical level is 10 ppm. Highly responsive in oilseeds (Mustard, Groundnut) and pulses.", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}, {"id": null, "text": "2. INTEGRATED NUTRIENT MANAGEMENT (INM) RECOMMENDATIONS\n- Combine 70% chemical fertilizers with 30% organic manures and Azotobacter / Rhizobium / PSB biofertilizers.\n- Incorporate legume green manures (Dhaincha - Sesbania aculeata or Sunn hemp) before Kharif planting.", "source": "soil_health_and_nutrient_management.txt", "page": 1, "topic": "", "crop": "General / Multi-Crop"}];

const AGRI_STOPWORDS = new Set([
  'what', 'is', 'the', 'of', 'in', 'and', 'to', 'for', 'are', 'a', 'an', 'how', 'why', 'can',
  'should', 'do', 'does', 'with', 'from', 'at', 'by', 'this', 'that', 'these', 'those', 'it',
  'its', 'or', 'as', 'on', 'be', 'tell', 'me', 'about', 'explain', 'give', 'detail', 'details'
]);

const AGRI_DOMAIN_KEYWORDS = new Set([
  'crop', 'crops', 'plant', 'plants', 'farm', 'farming', 'soil', 'pest', 'pests', 'disease', 'diseases',
  'blight', 'rust', 'leaf', 'leaves', 'seed', 'seeds', 'water', 'irrigation', 'fertigation', 'fertilizer',
  'fertilizers', 'manure', 'npk', 'drip', 'hydroponic', 'hydroponics', 'vertical', 'polyhouse', 'greenhouse',
  'solar', 'tractor', 'drone', 'drones', 'wheat', 'rice', 'paddy', 'tomato', 'tomatoes', 'cotton', 'chilli',
  'maize', 'corn', 'mustard', 'spray', 'pesticide', 'pesticides', 'fungicide', 'fungicides', 'harvest',
  'yield', 'weather', 'mandi', 'msp', 'subsidy', 'kusum', 'pmksy', 'rot', 'wilt', 'borer', 'aphid',
  'aphids', 'insect', 'insects', 'agriculture', 'organic', 'compost', 'carbon', 'precision', 'benefit',
  'benefits', 'sprinkler', 'agritech', 'modern', 'potash', 'nitrogen', 'phosphorus', 'zinc', 'iron',
  'drainage', 'humidity', 'loam', 'clay', 'salinity', 'alkaline', 'acidic', 'gypsum', 'pyrite', 'lime',
  'awd', 'alternate', 'wetting', 'drying', 'root', 'roots', 'stem', 'pod', 'grain', 'sowing', 'transplanting',
  'tillering', 'flowering', 'bph', 'planthopper', 'armyworm', 'pink', 'bollworm', 'whitefly', 'thrips',
  'imidacloprid', 'mancozeb', 'chlorantraniliprole', 'tricyclazole', 'hexaconazole', 'urea', 'dap', 'mop'
]);

function tokenizeQuery(q) {
  return (q || '').toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !AGRI_STOPWORDS.has(w));
}

function runClientRAG(question, imageData) {
  const q = (question || '').trim();
  const qLower = q.toLowerCase();
  
  // Greetings
  if (['hi', 'hello', 'hey', 'namaste', 'help'].includes(qLower.replace(/[^a-z]/g, ''))) {
    return {
      answer: '**Answer:**\nHello! I am your **AgriSense AI Assistant**.\n\n**Details:**\nI search verified Modern Farming datasets covering precision agriculture, crop management, AWD rice, fertigation, pest & disease control, soil health, and PM-KUSUM subsidies.\n\n**What to do:**\n- Try asking: *"What is precision agriculture?"*, *"What is fertigation?"*, or *"What are the benefits of modern farming?"*',
      citations: [{ source: 'Modern Farming Dataset', page: 'Verified Knowledge Base', topic: 'Agronomic Guidance' }],
      intent: 'Greeting'
    };
  }

  const tokens = tokenizeQuery(q);
  const isAgriRelated = tokens.some(t => AGRI_DOMAIN_KEYWORDS.has(t)) || Boolean(imageData);

  // Strict Out-of-Domain Refusal
  if (!isAgriRelated && tokens.length > 0) {
    return {
      answer: "I couldn't find this information in the provided dataset.",
      citations: [],
      intent: 'Out of Domain Query'
    };
  }

  // Score Chunks
  const scored = [];
  for (const c of EMBEDDED_CHUNKS) {
    const textLower = c.text.toLowerCase();
    const topicLower = (c.topic || '').toLowerCase();
    let score = 0;

    for (const t of tokens) {
      if (textLower.includes(t)) score += 2.0;
      if (topicLower.includes(t)) score += 4.0;
    }

    if (score > 0) {
      scored.push({ chunk: c, score });
    }
  }

  scored.sort((a, b) => b.score - a.score);
  const topChunks = scored.slice(0, 4).map(s => s.chunk);

  if (topChunks.length === 0) {
    return {
      answer: "I couldn't find this information in the provided dataset.",
      citations: [],
      intent: 'Out of Domain Query'
    };
  }

  // Extract lines
  const lines = [];
  const citations = [];
  for (const c of topChunks) {
    citations.push({ source: c.source, page: c.page, topic: c.topic });
    for (const rawLine of c.text.split('\n')) {
      const l = rawLine.trim();
      if (l.length > 20 && !l.startsWith('PAGE ') && !l.startsWith('Document:') && !l.startsWith('---')) {
        lines.push(l);
      }
    }
  }

  // Select key answers
  const primaryAns = lines.slice(0, 2).join(' ').replace(/^[-*•\d.\s]+/, '');
  const details = lines.slice(2, 5).map(l => '- ' + l.replace(/^[-*•\d.\s]+/, '')).join('\n');
  const action = lines.slice(5, 8).map(l => '- ' + l.replace(/^[-*•\d.\s]+/, '')).join('\n');

  const citeText = citations.slice(0, 2).map(c => `${c.source} (Page ${c.page})`).join(', ');

  let finalAnswer = `**Answer:**\n${primaryAns || 'Based on the verified Modern Farming dataset, follow standard agronomic protocol.'}\n\n`;
  if (details) {
    finalAnswer += `**Details / Key Principles:**\n${details}\n\n`;
  }
  if (action) {
    finalAnswer += `**What to do:**\n${action}\n\n`;
  }
  finalAnswer += `📄 *Verified Knowledge Source: ${citeText || 'Modern Farming Dataset'}*`;

  return {
    answer: finalAnswer,
    citations: citations,
    intent: 'Modern Farming RAG'
  };
}

if (typeof window !== 'undefined') {
  window.runClientRAG = runClientRAG;
}
